import sympy as sp
from sympy.matrices.normalforms import smith_normal_form
from sympy import ZZ
d={2:2,1:0}   # d_2: C_2 -> C_1 is 2, d_1 = 0
def dC(p): return d.get(p,0)
# basis of (C tensor C)_n: pairs (p,q), p+q=n, 0<=p,q<=2
B={n:[(p,n-p) for p in range(3) if 0<=n-p<=2] for n in range(-1,6)}
def D(n):
    M=sp.zeros(len(B[n-1]),len(B[n]))
    for c,(p,q) in enumerate(B[n]):
        if p>=1 and dC(p): M[B[n-1].index((p-1,q)),c]+=dC(p)
        if q>=1 and dC(q): M[B[n-1].index((p,q-1)),c]+=(-1)**p*dC(q)
    return M
for n in range(1,5): assert (D(n)*D(n+1)).is_zero_matrix if D(n).shape[1] and D(n+1).shape[1] and D(n).shape[0] else True
def homology(n):
    out=D(n); inn=D(n+1)
    rk_out=out.rank() if out.shape[0] and out.shape[1] else 0
    free=len(B[n])-rk_out
    if inn.shape[0] and inn.shape[1]:
        S=smith_normal_form(inn,domain=ZZ)
        diag=[abs(S[i,i]) for i in range(min(S.shape)) if S[i,i]!=0]
    else: diag=[]
    rank=free-len(diag)
    tors=sorted(x for x in diag if x!=1)
    return (rank,tors)
H=[homology(n) for n in range(5)]
assert H==[(1,[]),(0,[2,2]),(0,[2]),(0,[2]),(0,[])], H
# prediction from the Kunneth formula with H(C) = Z, Z/2, 0 (degrees 0,1,2)
import math
h={0:(1,[]),1:(0,[2]),2:(0,[])}
def tens(a,b):
    r=a[0]*b[0]; t=[]
    t+= b[1]*a[0] + a[1]*b[0]
    t+=[math.gcd(u,v) for u in a[1] for v in b[1]]
    return (r,[z for z in t if z!=1])
def tor(a,b): return (0,[z for z in [math.gcd(u,v) for u in a[1] for v in b[1]] if z!=1])
def add(*gs): return (sum(g[0] for g in gs), sorted(sum((g[1] for g in gs),[])))
pred=[]
for n in range(5):
    t=add(*[tens(h[p],h[n-p]) for p in range(3) if 0<=n-p<=2]) if any(0<=n-p<=2 for p in range(3)) else (0,[])
    s=add(*[tor(h[p],h[n-1-p]) for p in range(3) if 0<=n-1-p<=2]) if n>=1 else (0,[])
    pred.append(add(t,s))
assert pred==H, pred
